import { connect } from 'cloudflare:sockets';
import { probeWithConnect } from '../../lib/ech-probe/internal/probe.js';
import { handleRequest } from '../../src/worker.js';
const source = '539a750';
const fixed = { type: 'answer', records: [{name:'example.com',type:'HTTPS',ttl:60,rdata:{Https:{priority:1,target:'.',params:[]}}}] };
const safeCodes=new Set(['ABORTED','CERTIFICATE','CERTIFICATE_VERIFY','CRYPTO','DECRYPT','HOSTNAME','IO','NO_RETRY_CONFIG','TIMEOUT','LIMIT','MALFORMED','UNSUPPORTED','ALERT','FINISHED']);
function errorKind(error){const message=String(error?.message??'');return message.includes('proxy request failed, cannot connect to the specified address')?'PLATFORM_DESTINATION_DISALLOWED':message.includes('TCP Loop detected')?'TCP_LOOP':message.includes('Connection refused')?'CONNECTION_REFUSED':'UNCLASSIFIED';}
async function diagnose(mode){
 const state={stage:'start',opened:false,bytesWritten:0,bytesReceived:0};
 function observedConnect(address,options){
  state.stage='connect';const socket=connect(address,options);void socket.closed.catch(()=>{});
  return {opened:socket.opened.then(value=>{state.opened=true;state.stage='opened';return value;}),closed:socket.closed,
   writable:{getWriter(){const writer=socket.writable.getWriter();return {async write(bytes){state.stage='write';await writer.write(bytes);state.bytesWritten+=bytes.length;state.stage='written';},releaseLock(){writer.releaseLock();}};}},
   readable:{getReader(){const reader=socket.readable.getReader();return {async read(){state.stage='read';const part=await reader.read();if(part.value)state.bytesReceived+=part.value.length;state.stage=part.done?'eof':'received';return part;},releaseLock(){reader.releaseLock();}};}},
   close:()=>socket.close()};
 }
 try{
  if(mode==='diag-socket'){
   const socket=observedConnect({hostname:'scontent.xx.fbcdn.net',port:443},{secureTransport:'off',allowHalfOpen:false});let timer;
   try{await Promise.race([socket.opened,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Object.assign(new Error(),{code:'TIMEOUT'})),1500);})]);return {ok:true,...state};}
   finally{clearTimeout(timer);void socket.close().catch(()=>{});}
  }
  const result=await probeWithConnect(observedConnect,{hostname:'scontent.xx.fbcdn.net',port:443,serverName:'scontent.xx.fbcdn.net',timeoutMs:1500,maxBytes:65536,...(mode==='diag-library-verified'?{verifyCertificate:true}:{})});
  return {ok:true,...state,authenticated:result.authenticated,handshakeComplete:result.handshakeComplete,configBytes:result.bytes.length};
 }catch(error){return {ok:false,...state,code:safeCodes.has(error.code)?error.code:'UNCLASSIFIED',networkErrorKind:errorKind(error.cause??error)};}
}
export default {
 async fetch(request, env) {
  const mode = new URL(request.url).pathname.slice(1);
  const version = env.VERSION_METADATA.id;
  const headers = {'X-Diag-Version':version,'X-Diag-Source':source,'X-Diag-Target':'meta','Cache-Control':'no-store'};
  if (Date.now() > Number(env.RUN_EXPIRES)) return new Response('Expired',{status:410,headers});
  if (mode === 'ready') return Response.json({version,source},{headers});
  const sampleId=request.headers.get('X-Acceptance-Sample-Id');
  if (!/^[0-9a-f-]{36}$/.test(sampleId??'')) return new Response('Bad sample',{status:400,headers});
  if (!['fixed','production-default','production-verified','production-verified-cache','production-https','diag-socket','diag-library-default','diag-library-verified'].includes(mode)) return new Response('Not found',{status:404,headers});
  if(mode.startsWith('diag-')){const result=await diagnose(mode);console.info(JSON.stringify({event:'diag_result',sampleId,mode,version,source,...result}));return Response.json(result,{headers});}
  const actions = mode==='production-https' ? [{type:'queryUpstream',upstream:'control'}] : mode==='fixed' ? [fixed] : [fixed,{type:'probeEch',options:{hostname:'scontent.xx.fbcdn.net',port:443,serverName:'scontent.xx.fbcdn.net',timeoutMs:1500,maxBytes:65536,...(mode.startsWith('production-verified')?{verifyCertificate:true,...(mode==='production-verified-cache'?{cacheTtl:60}:{})}:{})}},{type:'applyEch'}];
  const url=new URL(request.url);url.pathname='/dns-query';url.search='';
  const response=await handleRequest(new Request(url,request),{DNS_UPSTREAMS:{control:{transport:'https',url:'https://cloudflare-dns.com/dns-query'}},DNS_CACHE:{read:false,write:false},DNS_RULE_MAIN:{order:0,rules:[{actions}]}},{requestId:sampleId});
  console.info(JSON.stringify({event:'diag_result',sampleId,mode,version,source,httpStatus:response.status}));
  const result=new Response(response.body,response);for(const [k,v]of Object.entries(headers))result.headers.set(k,v);return result;
 }
};

