import {parseEchConfigList} from '../../lib/ech-probe/config.js';import {createHash} from 'node:crypto';
import {setGlobalProxyFromEnv} from 'node:http';import {spawnSync} from 'node:child_process';import fs from 'node:fs';import path from 'node:path';import {randomUUID} from 'node:crypto';import {setTimeout as delay} from 'node:timers/promises';import {fileURLToPath} from 'node:url';import {query,decode} from '../../test/helpers/dns-wire.mjs';
const reg='HKCU:'+String.fromCharCode(92)+['Software','Microsoft','Windows','CurrentVersion','Internet Settings'].join(String.fromCharCode(92));
const command='(Get-ItemProperty -LiteralPath '+JSON.stringify(reg).replaceAll(String.fromCharCode(92)+String.fromCharCode(92),String.fromCharCode(92))+').ProxyServer';
let proxy=spawnSync('powershell.exe',['-NoProfile','-Command',command],{encoding:'utf8',timeout:10000}).stdout.trim();
if(proxy.includes('='))proxy=proxy.split(';').map(p=>p.split('=')).find(([k])=>k==='https'||k==='http')?.[1];
if(!/^(127[.]0[.]0[.]1|localhost):[0-9]+$/.test(proxy??''))throw Error('LOOPBACK_PROXY_UNAVAILABLE');
process.env.HTTP_PROXY='http://'+proxy;process.env.HTTPS_PROXY='http://'+proxy;setGlobalProxyFromEnv();
const dir=path.dirname(fileURLToPath(import.meta.url));
const log=fs.readFileSync(process.argv[2],'utf8');
const endpoint=log.match(/https:\/\/[^\s]+\.workers\.dev/)?.[0];const expectedVersion=log.match(/Current Version ID: ([0-9a-f-]+)/)?.[1];
if(!endpoint||!expectedVersion)throw Error('MISSING_DEPLOYMENT');
const ledgerFile=path.join(dir,'ledger.json');const ledger=fs.existsSync(ledgerFile)?JSON.parse(fs.readFileSync(ledgerFile,'utf8')):{cap:30,attempts:[],createdAt:new Date().toISOString()};
const modes=process.argv[3]==='baseline'?['ready','fixed','fixed','fixed','fixed','fixed','production-default']:process.argv.slice(3);
let failed=false;
for(const mode of modes){
 if(ledger.attempts.length>=ledger.cap)throw Error('REQUEST_CAP');
 if(ledger.attempts.length)await delay(1000);
 const row={sampleId:randomUUID(),targetLabel:'meta',mode,expectedVersion,startedAt:new Date().toISOString()};ledger.attempts.push(row);fs.writeFileSync(ledgerFile,JSON.stringify(ledger,null,2));
 try{
  const start=performance.now();const response=await fetch(endpoint+'/'+mode,mode==='ready'?{redirect:'manual',signal:AbortSignal.timeout(15000)}:{method:'POST',headers:{'Content-Type':'application/dns-message','X-Acceptance-Sample-Id':row.sampleId},body:query('example.com',65),redirect:'manual',signal:AbortSignal.timeout(15000)});
  row.httpStatus=response.status;row.version=response.headers.get('X-Diag-Version');row.source=response.headers.get('X-Diag-Source');row.targetLabelReceived=response.headers.get('X-Diag-Target');
  if(mode!=='stopped'&&(row.httpStatus!==200||row.version!==expectedVersion||row.source!=='539a750'||row.targetLabelReceived!=='meta'))throw Error('VERSION_OR_HTTP_MISMATCH');
  if(mode==='stopped'){row.stopped=response.status===410&&response.headers.get('X-Diag-State')==='stopped';await response.body?.cancel();if(!row.stopped)failed=true;}else if(mode==='ready'||mode.startsWith('diag-')){row.result=await response.json();if(mode!=='ready'&&row.result.ok!==true)failed=true;}
  else{const dns=decode(new Uint8Array(await response.arrayBuffer()));row.rcode=dns.flags&15;row.answerCount=dns.records.filter(r=>r.section===0).length;row.desiredEchSuccess=(mode==='fixed'||mode==='production-https')?undefined:row.rcode===0;if(dns.id!==0x4242)throw Error('DNS_ID_MISMATCH');if(row.rcode===0&&mode.startsWith('production-')&&mode!=='production-https'){
 const https=dns.records.find(r=>r.section===0&&r.type===65);if(!https)throw Error('ECH_ANSWER_MISSING');const data=https.data;let offset=2;while(offset<data.length){const size=data[offset++];if(size===0)break;if(size>63||offset+size>data.length)throw Error('ECH_ANSWER_INVALID');offset+=size;}
 let ech;while(offset+4<=data.length){const key=(data[offset]<<8)|data[offset+1],length=(data[offset+2]<<8)|data[offset+3];offset+=4;if(offset+length>data.length)throw Error('ECH_ANSWER_INVALID');if(key===5)ech=Uint8Array.from(data.slice(offset,offset+length));offset+=length;}
 if(!ech?.length)throw Error('ECH_CONFIG_MISSING');const parsed=parseEchConfigList(ech);row.echConfigBytes=ech.length;row.echConfigCount=parsed.configs.length;row.echSha256=createHash('sha256').update(ech).digest('hex');
}if(row.rcode!==0)failed=true;}
  row.clientLatencyMs=performance.now()-start;
 }catch(e){row.error=['VERSION_OR_HTTP_MISMATCH','DNS_ID_MISMATCH','ECH_ANSWER_MISSING','ECH_ANSWER_INVALID','ECH_CONFIG_MISSING'].includes(e.message)?e.message:'CLIENT_REQUEST_FAILED';failed=true;}
 fs.writeFileSync(ledgerFile,JSON.stringify(ledger,null,2));console.log(JSON.stringify(row));
 if(row.error)break;
 if(mode==='fixed'&&row.rcode!==0)break;
}
console.log(JSON.stringify({clientAttemptsUsed:ledger.attempts.length,requestCap:ledger.cap,desiredOutcomePassed:!failed}));if(failed)process.exitCode=2;

